// SigFall-Stale - fallback chain demo
var chain = [
  { name: "live backend", ok: false },
  { name: "SigFall-Stale", ok: true }
];
var served = null;
for (var i = 0; i < chain.length; i++) { if (chain[i].ok) { served = chain[i].name; break; } }
console.log("Pattern: SigFall-Stale | Serves: signed stale copy");
console.log("Backend down -> fallback engaged: " + served);
console.log(served ? "RESULT: user still gets a page -> PASS" : "RESULT: outage");

